#!/usr/bin/env python3
"""Map edits of lane c16-repair-owed-record-r15. Reads before/OBSTRUCTION_MAP.md, writes the map given as argv[1]
(default: ../OBSTRUCTION_MAP.md). Every anchor must occur exactly once. Sources and quotes: sources.py."""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, 'before', 'OBSTRUCTION_MAP.md')
DST = sys.argv[1] if len(sys.argv) > 1 else os.path.normpath(os.path.join(HERE, '..', 'OBSTRUCTION_MAP.md'))
t = open(SRC, encoding='utf-8').read()
REF2 = '`c15-referee-r14-independent-checkpoint`'
n_edits = 0

def after(anchor, add):
    global t, n_edits
    assert t.count(anchor) == 1, (t.count(anchor), anchor[:80])
    t = t.replace(anchor, anchor + add); n_edits += 1

def repl(anchor, new):
    global t, n_edits
    assert t.count(anchor) == 1, (t.count(anchor), anchor[:80])
    t = t.replace(anchor, new); n_edits += 1

def line_after(prefix, newline):
    """insert newline after the unique line that starts with prefix"""
    global t, n_edits
    lines = t.split('\n')
    hit = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(hit) == 1, (len(hit), prefix)
    assert '\n' not in newline
    lines.insert(hit[0] + 1, newline)
    t = '\n'.join(lines); n_edits += 1

